import{_ as a,o as e,c as o,a2 as t}from"./chunks/framework.BS0bAV7E.js";const _=JSON.parse('{"title":"Wiki 同步机制","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/wiki-sync.md","filePath":"zh/release/wiki-sync.md"}'),l={name:"zh/release/wiki-sync.md"};function r(c,i,s,d,n,h){return e(),o("div",null,[...i[0]||(i[0]=[t('<h1 id="wiki-同步机制" tabindex="-1">Wiki 同步机制 <a class="header-anchor" href="#wiki-同步机制" aria-label="Permalink to &quot;Wiki 同步机制&quot;">​</a></h1><p><code>tools/sync_wiki.sh</code> - docs/ 目录树也存在于 GitHub Wiki 上。</p><h2 id="同步内容" tabindex="-1">同步内容 <a class="header-anchor" href="#同步内容" aria-label="Permalink to &quot;同步内容&quot;">​</a></h2><p>Wiki 获取的是经过筛选的页面集（首页、快速上手、构建、架构概览、调试与 QEMU、L1 扩展指南、用户手册、常见问题、发布说明，以及各领域的手册），这些页面都从相同的 <code>docs/</code> 源文件生成 - 一个创作源，两个输出（网站上的文档中心，以及 GitHub 上的 Wiki）。</p><h2 id="如何同步" tabindex="-1">如何同步 <a class="header-anchor" href="#如何同步" aria-label="Permalink to &quot;如何同步&quot;">​</a></h2><ol><li>脚本将 <code>docs/</code> 页面映射到 Wiki 页面名称（映射表存储在脚本中）。</li><li>将相对链接重写为 Wiki 页面链接。</li><li>克隆 <code>{repo}.wiki</code>，写入页面，提交，推送。</li></ol><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><ul><li>所有映射的 Wiki 页面均存在（脚本会打印列表）。</li><li>链接检查：映射集合中没有红色链接。</li><li>内容一致性：Wiki 页面和 docs 页面渲染相同的 markdown 源（脚本在推送前会比较它们的差异）。</li></ul><h2 id="运行时机" tabindex="-1">运行时机 <a class="header-anchor" href="#运行时机" aria-label="Permalink to &quot;运行时机&quot;">​</a></h2><p>在发布时（docs/ 更新合并后）以及针对仅 docs 的更新按需运行。</p>',10)])])}const u=a(l,[["render",r]]);export{_ as __pageData,u as default};
